I kept the first version very direct. Four loops choose the four positions, and a sorted copy of each group lets a set remove duplicate answers. It is not suitable for large inputs, but it is easy to check against small test cases.

```cpp
class Solution {
public:
    vector<vector<int>> fourSum(vector<int>& nums, int target) {
        int n = nums.size();
        set<vector<int>> uniqueAnswers;

        for (int a = 0; a < n; ++a) {
            for (int b = a + 1; b < n; ++b) {
                for (int c = b + 1; c < n; ++c) {
                    for (int d = c + 1; d < n; ++d) {
                        long long sum = static_cast<long long>(nums[a]) + nums[b] + nums[c] + nums[d];
                        if (sum == target) {
                            vector<int> group = {nums[a], nums[b], nums[c], nums[d]};
                            sort(group.begin(), group.end());
                            uniqueAnswers.insert(group);
                        }
                    }
                }
            }
        }

        return vector<vector<int>>(uniqueAnswers.begin(), uniqueAnswers.end());
    }
};
```

For example, with `nums = [1, 0, -1, 0, -2, 2]` and target `0`, the loops find groups such as `[-1, 0, 0, 1]`. Sorting before insertion makes the same value group look identical even when its indexes are different.

The code does not change the input array. An empty array or an array with fewer than four values simply produces an empty result because no four indexes can be chosen.

Time complexity: `O(n^4)`.

Space complexity: `O(q)`, where `q` is the number of different answers, plus the set storage.

Sorting turns the problem into a controlled search. After fixing the first two numbers, two pointers scan the rest. Equal values are skipped at every level, so the returned rows are unique without a separate set.

```cpp
class Solution {
public:
    vector<vector<int>> fourSum(vector<int>& nums, int target) {
        sort(nums.begin(), nums.end());
        vector<vector<int>> answer;
        int n = nums.size();

        for (int i = 0; i + 3 < n; ++i) {
            if (i > 0 && nums[i] == nums[i - 1]) {
                continue;
            }

            long long smallest = static_cast<long long>(nums[i]) + nums[i + 1] + nums[i + 2] + nums[i + 3];
            if (smallest > target) {
                break;
            }

            long long largest = static_cast<long long>(nums[i]) + nums[n - 1] + nums[n - 2] + nums[n - 3];
            if (largest < target) {
                continue;
            }

            for (int j = i + 1; j + 2 < n; ++j) {
                if (j > i + 1 && nums[j] == nums[j - 1]) {
                    continue;
                }

                long long pairSmallest = static_cast<long long>(nums[i]) + nums[j] + nums[j + 1] + nums[j + 2];
                if (pairSmallest > target) {
                    break;
                }

                long long pairLargest = static_cast<long long>(nums[i]) + nums[j] + nums[n - 1] + nums[n - 2];
                if (pairLargest < target) {
                    continue;
                }

                int left = j + 1;
                int right = n - 1;

                while (left < right) {
                    long long sum = static_cast<long long>(nums[i]) + nums[j] + nums[left] + nums[right];

                    if (sum == target) {
                        answer.push_back({nums[i], nums[j], nums[left], nums[right]});
                        ++left;
                        --right;

                        while (left < right && nums[left] == nums[left - 1]) {
                            ++left;
                        }
                        while (left < right && nums[right] == nums[right + 1]) {
                            --right;
                        }
                    } else if (sum < target) {
                        ++left;
                    } else {
                        --right;
                    }
                }
            }
        }

        return answer;
    }
};
```

The input array is changed because it is sorted. As a dry run, for `[-2, -1, 0, 0, 1, 2]` and target `0`, fixing `-2` and `-1` leaves pointers at `0` and `2`, which give `-1` as the total, so the left pointer moves. The scan eventually records `[-2, -1, 1, 2]`.

The long long sums protect the additions when values are near the integer limits. The early smallest and largest checks are optional, but they avoid many impossible searches.

Time complexity: `O(n^3)` after sorting.

Space complexity: `O(1)` extra space, excluding the output. The sort changes `nums`.

This version stores every pair by its sum. A pair from one bucket is matched with a pair from the complementary bucket, and the four indexes must be different. A set of lists removes repeated value combinations.

```java
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

class Solution {
    public List<List<Integer>> fourSum(int[] nums, int target) {
        Map<Long, List<int[]>> pairsBySum = new HashMap<>();
        int n = nums.length;

        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                long sum = (long) nums[i] + nums[j];
                pairsBySum.computeIfAbsent(sum, key -> new ArrayList<>())
                          .add(new int[] {i, j});
            }
        }

        Set<List<Integer>> uniqueAnswers = new HashSet<>();

        for (Map.Entry<Long, List<int[]>> entry : pairsBySum.entrySet()) {
            long firstSum = entry.getKey();
            long secondSum = (long) target - firstSum;

            if (!pairsBySum.containsKey(secondSum)) {
                continue;
            }

            for (int[] first : entry.getValue()) {
                for (int[] second : pairsBySum.get(secondSum)) {
                    if (first[0] == second[0] || first[0] == second[1]
                            || first[1] == second[0] || first[1] == second[1]) {
                        continue;
                    }

                    List<Integer> values = new ArrayList<>();
                    values.add(nums[first[0]]);
                    values.add(nums[first[1]]);
                    values.add(nums[second[0]]);
                    values.add(nums[second[1]]);
                    values.sort(Integer::compareTo);
                    uniqueAnswers.add(values);
                }
            }
        }

        return new ArrayList<>(uniqueAnswers);
    }
}
```

The map makes the sum lookup fast. For instance, if one pair totals `5` and the target is `9`, only pairs totaling `4` need to be checked against it. The index test is important because two pairs cannot reuse the same array position.

A short edge case is `nums = [2, 2, 2, 2]` and target `8`. Many pair combinations are created, but the set returns only `[2, 2, 2, 2]`. Empty input or fewer than four values returns an empty list naturally.

Time complexity: pair creation takes `O(n^2)`, while combining pair buckets can take `O(n^4)` in the worst case.

Space complexity: `O(n^2)` for the stored pairs, besides the answer set.

Here the first three positions are selected with loops, and the fourth value is searched in the sorted suffix. A set keeps only one copy of each sorted quadruplet. This is a little different from the usual two-pointer scan and is useful for seeing how binary search can finish the last part.

```python
class Solution:
    def fourSum(self, nums, target):
        nums.sort()
        answer = set()
        n = len(nums)

        for i in range(n - 3):
            if i > 0 and nums[i] == nums[i - 1]:
                continue

            for j in range(i + 1, n - 2):
                if j > i + 1 and nums[j] == nums[j - 1]:
                    continue

                for k in range(j + 1, n - 1):
                    if k > j + 1 and nums[k] == nums[k - 1]:
                        continue

                    needed = target - nums[i] - nums[j] - nums[k]
                    left = k + 1
                    right = n - 1

                    while left <= right:
                        middle = (left + right) // 2
                        if nums[middle] == needed:
                            answer.add((nums[i], nums[j], nums[k], nums[middle]))
                            break
                        if nums[middle] < needed:
                            left = middle + 1
                        else:
                            right = middle - 1

        return [list(group) for group in sorted(answer)]
```

For a quick example, after choosing `1, 0, -1` from the input, the code calculates the missing value instead of scanning all remaining values. Binary search then checks whether that value exists after index `k`.

The duplicate checks reduce repeated work, while the set is still needed because different choices can produce the same values. The array is sorted in place. If there are fewer than four numbers, all loop ranges are empty and the result is `[]`.

Time complexity: `O(n^3 log n)` after sorting.

Space complexity: `O(q)` for the set of answers.

A recursive helper makes the four-number case look like a smaller version of the same problem. It picks one value, reduces the remaining count, and uses two pointers when only two values are left. Sorting first gives both duplicate skipping and useful sum checks.

```python
class Solution:
    def fourSum(self, nums, target):
        nums.sort()
        result = []

        def search(start, count, remaining, path):
            if count == 2:
                left = start
                right = len(nums) - 1

                while left < right:
                    total = nums[left] + nums[right]
                    if total == remaining:
                        result.append(path + [nums[left], nums[right]])
                        left += 1
                        right -= 1
                        while left < right and nums[left] == nums[left - 1]:
                            left += 1
                        while left < right and nums[right] == nums[right + 1]:
                            right -= 1
                    elif total < remaining:
                        left += 1
                    else:
                        right -= 1
                return

            if len(nums) - start < count:
                return

            for index in range(start, len(nums) - count + 1):
                if index > start and nums[index] == nums[index - 1]:
                    continue

                smallest = nums[index]
                largest = nums[index]
                for offset in range(1, count):
                    smallest += nums[index + offset]
                    largest += nums[-offset]

                if smallest > remaining:
                    break
                if largest < remaining:
                    continue

                search(index + 1, count - 1, remaining - nums[index], path + [nums[index]])

        search(0, 4, target, [])
        return result
```

The array is sorted in place. For a quick dry run, after choosing `-2` from `[-2, -1, 0, 0, 1, 2]`, the helper searches for three numbers totaling `2`. The next choice and the final two-pointer scan finish the quadruplet.

The `smallest` and `largest` checks stop branches that cannot reach the needed sum. They also use Python integers, so large target additions do not overflow.

Time complexity: about `O(n^3)` in the usual bound for 4-sum after sorting.

Space complexity: `O(n)` for recursion and the current path, not counting the returned answers.

